consumer_relation.native_case:
"catalyst":
	var poison: int = _sget(target.statuses, "poison")
	if poison > 0:
		add_status_enemy(cb, target, "poison", poison * (_ji(fx["n"]) - 1), run)

consumer_relation.historical_case:
"catalyst":
	var poison: int = _sget(target.statuses, "poison")
	if poison > 0:
		var multiplier: int = _ji(fx["n"])
		if run.aspect == 1 and _sget(target.statuses, "mistbound") > 0:
			multiplier += _ji(fx.get("mistboundBonus", 0))
			add_status_enemy(cb, target, "mistbound", -1, run)
		add_status_enemy(cb, target, "poison", poison * (multiplier - 1), run)

